import { Action, Selector, State, StateContext } from "@ngxs/store";
import { Injectable } from "@angular/core";

import { MenuStoreModel } from "../model/menu-store.model";
import { SwitchMainMenuIsOpen } from "../action/menu-store.action";

@State<MenuStoreModel>({
  name: "menuStoreState",
  defaults: {
    mainMenuIsOpen: false,
    options: [
      {
        id: "users",
        label: "Users",
        link: "/users",
        isActive: true
      },
      {
        id: "companies",
        label: "Companies",
        link: "/companies",
        isActive: false
      },
      {
        id: "resumes",
        label: "Resumes",
        link: "/resumes",
        isActive: false
      }
    ]
  }
})
@Injectable({ providedIn: "root" })
export class MenuStoreState {
  @Selector()
  static getMainMenuIsOpen(state: MenuStoreModel) {
    return state.mainMenuIsOpen;
  }

  @Selector()
  static getOptions(state: MenuStoreModel) {
    return state.options;
  }

  @Action(SwitchMainMenuIsOpen)
  switchMainMenuIsOpen(context: StateContext<MenuStoreModel>) {
    const state = context.getState();
    context.setState({
      ...state,
      mainMenuIsOpen: !state.mainMenuIsOpen
    });
  }
}

import { Action, Selector, State, StateContext } from "@ngxs/store";
import { Injectable } from "@angular/core";

import { ScreenStoreModel } from "../model/screen-store.model";
import { SetScreenType } from "../action/screen-store.action";

@State<ScreenStoreModel>({
  name: "screenStoreState",
  defaults: {
    screenSize: 0
  }
})
@Injectable({ providedIn: "root" })
export class ScreenStoreState {
  @Selector()
  static getScreenSize(state: ScreenStoreModel) {
    return state.screenSize;
  }
  
  @Action(SetScreenType)
  setScreenType(context: StateContext<ScreenStoreModel>, action: SetScreenType) {
    const state = context.getState();
    context.setState({
      ...state,
      screenSize: action.screenSize
    });
  }
}

