import { ApplicationConfig, provideBrowserGlobalErrorListeners } from "@angular/core";
import { provideRouter } from "@angular/router";
import { provideStore } from "@ngxs/store";
import { withNgxsReduxDevtoolsPlugin } from "@ngxs/devtools-plugin";

import { MenuStoreState } from "../store/state/menu-store.state";
import { routesConfig } from "./routes.config";
import { ScreenStoreState } from "../store/state/screen-store.state";

export class ProviderConfig {
    static getProvider(): ApplicationConfig {
        return {
            providers: [
                provideBrowserGlobalErrorListeners(),
                provideRouter(routesConfig),
                provideStore([MenuStoreState, ScreenStoreState], withNgxsReduxDevtoolsPlugin())
            ],
        };
    }
}

export class SetScreenType {
    static readonly type = "[ScreenStoreState] Set Screen Size";

    constructor(public screenSize: number) {}
}

export class SwitchMainMenuIsOpen {
    static readonly type = "[MenuStoreState] Switch Main Menu Is Open";
}

