import { Store } from "@ngxs/store";

import { HamburgerComponent } from "../hamburger/hamburget.component";
import { MenuComponent } from "../menu/menu.component";
import { MenuStoreState } from "../../store/state/menu-store.state";
import { ScreenStoreState } from "../../store/state/screen-store.state";

@Component({
    selector: "app-nav-component",
    templateUrl: "./nav.component.html",
    styleUrl: "./nav.component.scss",
    imports: [HamburgerComponent, MenuComponent, AsyncPipe]
})
export class NavComponent {
    store = inject(Store);

    mainMenuIsOpen$ = this.store.select(MenuStoreState.getMainMenuIsOpen);

    screenSize$ = this.store.select(ScreenStoreState.getScreenSize);
}

components.templateData:
@let mainMenuIsOpen = mainMenuIsOpen$ | async;
@let screenSize = screenSize$ | async;

<nav class="nav">
    @if (screenSize && screenSize <= 768) {
        <div class="nav__hamburger">
            <app-hamburger-component></app-hamburger-component>
        </div>
    }
    @if (mainMenuIsOpen === true || (screenSize && screenSize > 768)) {
        <app-menu-component></app-menu-component>
    }
</nav>

